import http from 'node:http'
import { WebSocketServer } from 'ws'
import { setupWSConnection, docs } from '@y/websocket-server/utils'

/**
 * Room IDs are generated by the Next.js app (src/lib/room-id.ts).
 * Keep this pattern in sync with ROOM_ID_PATTERN there.
 */
export const ROOM_ID_PATTERN = /^[23456789abcdefghjkmnpqrstuvwxyz]{10}$/

/**
 * @typedef {object} SyncServerOptions
 * @property {number} [port] 0 picks a free port (used by tests)
 * @property {string} [host]
 * @property {string[]} [allowedOrigins] empty = allow any origin (local development only)
 * @property {number} [maxPayloadBytes] largest single WebSocket message accepted
 * @property {number} [maxRooms] rooms held in memory at once
 * @property {number} [maxConnectionsPerIp]
 * @property {number} [roomTtlMs] how long an empty room is kept before it is dropped from memory
 * @property {number} [sweepIntervalMs]
 * @property {(msg: string) => void} [log]
 */

/** @param {import('node:http').IncomingMessage} req */
const clientIp = (req) => {
  const forwarded = req.headers['x-forwarded-for']
  const first = Array.isArray(forwarded) ? forwarded[0] : forwarded?.split(',')[0]
  return (first || req.socket.remoteAddress || 'unknown').trim()
}

/**
 * @param {import('node:stream').Duplex} socket
 * @param {number} status
 * @param {string} reason
 */
const reject = (socket, status, reason) => {
  socket.write(`HTTP/1.1 ${status} ${reason}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`)
  socket.destroy()
}

/**
 * Creates the CodeRoom sync server: a plain y-websocket relay with room-name validation,
 * an origin allowlist, bounded message size, connection caps, a health endpoint and
 * an idle-room sweep so in-memory documents do not grow without limit.
 * Documents live in memory only (no persistence): a room is lost after it stays empty for roomTtlMs.
 * @param {SyncServerOptions} [options]
 */
export function createSyncServer (options = {}) {
  const {
    port = 1234,
    host = '127.0.0.1',
    allowedOrigins = [],
    maxPayloadBytes = 1024 * 1024,
    maxRooms = 500,
    maxConnectionsPerIp = 20,
    roomTtlMs = 30 * 60 * 1000,
    sweepIntervalMs = 60 * 1000,
    log = () => {}
  } = options

  /** @type {Map<string, number>} room -> time it became empty */
  const emptySince = new Map()
  /** @type {Map<string, number>} */
  const connectionsPerIp = new Map()

  const wss = new WebSocketServer({ noServer: true, maxPayload: maxPayloadBytes })

  const server = http.createServer((req, res) => {
    if (req.url === '/healthz' || req.url === '/') {
      res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' })
      res.end(JSON.stringify({ ok: true, rooms: docs.size, connections: wss.clients.size }))
      return
    }
    res.writeHead(404, { 'Content-Type': 'text/plain' })
    res.end('not found')
  })

  server.on('upgrade', (req, socket, head) => {
    const url = new URL(req.url || '/', 'http://localhost')
    const roomId = url.pathname.slice(1)
    if (!ROOM_ID_PATTERN.test(roomId)) return reject(socket, 400, 'Bad Request')

    const origin = req.headers.origin
    if (allowedOrigins.length > 0 && (!origin || !allowedOrigins.includes(origin))) {
      log(`rejected origin ${origin ?? '(none)'}`)
      return reject(socket, 403, 'Forbidden')
    }
    if (!docs.has(roomId) && docs.size >= maxRooms) return reject(socket, 503, 'Service Unavailable')

    const ip = clientIp(req)
    const current = connectionsPerIp.get(ip) ?? 0
    if (current >= maxConnectionsPerIp) return reject(socket, 429, 'Too Many Requests')

    wss.handleUpgrade(req, socket, head, (ws) => {
      connectionsPerIp.set(ip, current + 1)
      emptySince.delete(roomId)
      setupWSConnection(ws, req, { docName: roomId })
      // Registered after setupWSConnection so its own close handler has already removed this connection.
      ws.on('close', () => {
        const left = (connectionsPerIp.get(ip) ?? 1) - 1
        if (left <= 0) connectionsPerIp.delete(ip)
        else connectionsPerIp.set(ip, left)
        const doc = docs.get(roomId)
        if (doc && doc.conns.size === 0) emptySince.set(roomId, Date.now())
      })
    })
  })

  /** Drops rooms that have been empty longer than roomTtlMs. Returns the number removed. */
  const sweep = (now = Date.now()) => {
    let removed = 0
    for (const [name, since] of emptySince) {
      const doc = docs.get(name)
      if (!doc) {
        emptySince.delete(name)
        continue
      }
      if (doc.conns.size > 0) {
        emptySince.delete(name)
        continue
      }
      if (now - since >= roomTtlMs) {
        doc.destroy()
        docs.delete(name)
        emptySince.delete(name)
        removed++
      }
    }
    if (removed > 0) log(`swept ${removed} idle room(s)`)
    return removed
  }

  const timer = setInterval(sweep, sweepIntervalMs)
  timer.unref()

  return {
    server,
    sweep,
    /** @returns {Promise<{ port: number, host: string }>} */
    listen: () =>
      new Promise((resolve, reject) => {
        server.once('error', reject)
        server.listen(port, host, () => {
          const address = /** @type {import('node:net').AddressInfo} */ (server.address())
          resolve({ port: address.port, host })
        })
      }),
    close: () =>
      new Promise((resolve) => {
        clearInterval(timer)
        for (const client of wss.clients) client.terminate()
        wss.close()
        // Each in-memory doc owns an awareness interval; destroy them so the process can exit.
        for (const [name, doc] of docs) {
          doc.destroy()
          docs.delete(name)
        }
        emptySince.clear()
        server.close(() => resolve(undefined))
      })
  }
}
